CREATE TABLE public.e2e_device_keys (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL, device_id TEXT NOT NULL, public_key TEXT NOT NULL, algo TEXT NOT NULL DEFAULT 'x25519-sealedbox', last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (user_id, device_id)); CREATE INDEX idx_e2e_device_keys_user ON public.e2e_device_keys(user_id); ALTER TABLE public.e2e_device_keys ENABLE ROW LEVEL SECURITY; CREATE POLICY "e2e_read_all" ON public.e2e_device_keys FOR SELECT TO authenticated USING (true); CREATE POLICY "e2e_insert_own" ON public.e2e_device_keys FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY "e2e_update_own" ON public.e2e_device_keys FOR UPDATE TO authenticated USING (auth.uid() = user_id); CREATE POLICY "e2e_delete_own" ON public.e2e_device_keys FOR DELETE TO authenticated USING (auth.uid() = user_id);